package se.lu.ics.models;

import java.math.BigDecimal;

/**
 * Represents a product in the Marvix system.
 *
 * Used to transfer product data between the data access layer and
 * the application controllers.
 */
public class Product {

    private final int productId;
    private final String productName;
    private final BigDecimal price;

    /**
     * Creates a product from data retrieved from the database.
     *
     * @param productId   unique product ID generated by SQL Server
     * @param productName product name
     * @param price       product price
     */
    public Product(
            int productId,
            String productName,
            BigDecimal price) {

        this.productId = productId;
        this.productName = productName;
        this.price = price;
    }

    /**
     * Returns the product ID.
     *
     * @return product ID
     */
    public int getProductId() {
        return productId;
    }

    /**
     * Returns the product name.
     *
     * @return product name
     */
    public String getProductName() {
        return productName;
    }

    /**
     * Returns the product price.
     *
     * @return product price
     */
    public BigDecimal getPrice() {
        return price;
    }
}
